head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[accordion > M > getPanelInfo]<br/>Accordion 컴포넌트의 전체 패널의 속성 정보를 배열로 반환합니다.",
    "validation" : [
        "getPanelInfo() 호출 시 패널의 열림/닫힘 상태에 관계없이 전체 패널의 속성 정보를 반환합니다.",
        "반환값은 2차원 배열(Array) 로 첫번째 원소(result[0]) 에 전체 패널의 속성 정보가 배열로 전달됩니다.",
        "반환된 객체의 result.id 는 패널의 렌더링 ID (String) 를 갖습니다.",
        "반환된 객체의 result.style 은 패널의 style 속성값 (String) 을 갖습니다.",
        "반환된 객체의 result.className 은 패널의 className 속성값 (String) 을 갖습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // customClass CSS 동적 추가 (panels2 의 className 시각 효과용)
    // 엔진(accordion.js:1265) 이 'w2panels' + className 을 공백 없이 연결하여 .customClass selector 매칭 안 됨 → attribute substring 매칭으로 우회
    let styleEl = document.createElement("style");
    styleEl.textContent = "[class*='customClass'] { background-color: #ffff99 !important; border: 2px solid red !important; }";
    document.head.appendChild(styleEl);

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (별도 옵션 없음)
    let properties = {
    };

    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="* panels1 : 기본 (style/class 미지정) → result.style/className 기본값 검증용"', '', 'label1');
    $c.gcm.createLabel('label="* panels2 : id=myUser2, style=background-color:#eee;, class=customClass (샘플 내 정의: 노란 배경 + 빨간 테두리) → result.id/style/className 값 검증용"', '', 'label2');
    $c.gcm.createLabel('label="* panels3 : disabledPanels=true (닫힘 상태) → 열림/닫힘 무관 전체 반환 검증용"', '', 'label3');
    $c.gcm.createLabel('label="* getPanelInfo() → 2차원 배열 반환 (result[colIdx][panelIdx]) / 각 패널 정보 = { id, style, className }"', '', 'label4');
    $c.gcm.createLabel('label="* 첫번째 원소(result[0]) 에 전체 패널의 속성 정보가 배열로 전달됨"', '', 'label5');

    strTarget += '<w2:accordion ' + strNameSpace + ' ' + cList + ' id="" style="width:240px; height:320px;">';
    strTarget += '<w2:panels style="" id="panels1" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle1" label="panelTitle1"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent1">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel1"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="background-color:#eee;" id="myUser2" class="customClass">';
    strTarget += '<w2:panelTitle style="" id="panelTitle2" label="panelTitle2 (style/class 적용)"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent2">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel2"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels3" class="" disabledPanels="true">';
    strTarget += '<w2:panelTitle style="" id="panelTitle3" label="panelTitle3 (disabled, 닫힘)"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent3">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel3"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '</w2:accordion>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "accordion",
        strTarget,
        grp_comp
    );
}



// getPanelInfo() 호출 — 전체 패널의 속성 정보 2차원 배열 출력
scwin.btn_getPanelInfo_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== getPanelInfo() 호출 =====");
    let result = target1.getPanelInfo();

    if (Array.isArray(result) && result.length > 0) {
        let firstColPanels = result[0];
        for (let i = 0; i < firstColPanels.length; i++) {
            let p = firstColPanels[i];
            wf_body_bottom.getObj("scwin").setReturnValue("------- 패널[" + i + "] -------");
            wf_body_bottom.getObj("scwin").setReturnValue("result[0][" + i + "].id : " + p.id);
            wf_body_bottom.getObj("scwin").setReturnValue("result[0][" + i + "].style : " + p.style);
            wf_body_bottom.getObj("scwin").setReturnValue("result[0][" + i + "].className : " + p.className);
        }
    }
};
